package com.example.microsave.contribution.controller;
import com.example.microsave.contribution.dto.ContributionDTO;import com.example.microsave.contribution.service.ContributionService;import jakarta.validation.Valid;import java.math.BigDecimal;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/contributions") public class ContributionController {private final ContributionService s;public ContributionController(ContributionService s){this.s=s;}@GetMapping public List<ContributionDTO> all(){return s.all();}@GetMapping("/{id}")public ContributionDTO one(@PathVariable Long id){return s.one(id);}@GetMapping("/member/{memberId}")public List<ContributionDTO> member(@PathVariable Long memberId){return s.byMember(memberId);}@GetMapping("/member/{memberId}/total")public BigDecimal totalMember(@PathVariable Long memberId){return s.totalForMember(memberId);}@GetMapping("/total")public BigDecimal total(){return s.total();}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ContributionDTO save(@Valid @RequestBody ContributionDTO d){return s.save(d);}@PutMapping("/{id}")public ContributionDTO update(@PathVariable Long id,@Valid @RequestBody ContributionDTO d){return s.update(id,d);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){s.delete(id);}}
